20	@GrpcService(interceptors = LocalImportIdentity.class, blendWithGlobalInterceptors = true)
21	@Profile("local-import")
22	@ConditionalOnProperty(name = "inventory.import.dispatch.enabled", havingValue = "true")
23	class ImportWorkerGrpcService extends ImportWorkerGrpc.ImportWorkerImplBase {
24	    private static final Pattern FAILURE_CODE = Pattern.compile("[A-Z][A-Z0-9_]{0,63}");
25	
26	    private final ImportProcessing processing;
27	
28	    ImportWorkerGrpcService(ImportProcessing processing) {
29	        this.processing = processing;
30	    }
31	
32	    @Override
33	    public void stage(StageImportRequest request, StreamObserver<StageImportUpdate> response) {
34	        int pass = request.getPassNumber();
35	        int attempt = request.getAttempt();
36	        if (pass < 0 || pass > 2 || attempt < 1 || attempt > 3) {
37	            throw Status.INVALID_ARGUMENT.withDescription("Invalid staging pass or attempt").asRuntimeException();
38	        }
39	        UUID job = ImportGrpcService.jobId(request.getJobId());
40	        try {
41	            String generation = processing.stage(job, pass * 10 + attempt, rows -> {
42	                if (Context.current().isCancelled()) {
43	                    throw Status.CANCELLED.asRuntimeException();
44	                }
45	                response.onNext(StageImportUpdate.newBuilder().setRowsRead(rows).build());
46	            });
47	            response.onNext(StageImportUpdate.newBuilder().setGeneration(generation).build());
48	            response.onCompleted();
49	        } catch (InventoryCsvReader.FileProblem invalid) {
50	            response.onError(Status.INVALID_ARGUMENT.withDescription(invalid.getMessage()).asRuntimeException());
51	        }
52	    }
53	
54	    @Override
55	    public void apply(ApplyImportRequest request, StreamObserver<ApplyImportResponse> response) {
56	        boolean finished = processing.apply(ImportGrpcService.jobId(request.getJobId()),
57	            ImportGrpcService.jobId(request.getGeneration()));
58	        response.onNext(ApplyImportResponse.newBuilder().setFinished(finished).build());
59	        response.onCompleted();
60	    }
61	
62	    @Override
63	    public void fail(FailImportRequest request, StreamObserver<Empty> response) {
64	        if (!FAILURE_CODE.matcher(request.getCode()).matches()) {
65	            throw Status.INVALID_ARGUMENT.withDescription("Invalid import failure code").asRuntimeException();
66	        }
67	        processing.fail(ImportGrpcService.jobId(request.getJobId()), request.getCode());
68	        response.onNext(Empty.getDefaultInstance());
69	        response.onCompleted();
70	    }
71	}
