 5	from temporalio.exceptions import ActivityError, ApplicationError
 6	
 7	RETRY = RetryPolicy(maximum_attempts=3)
 8	STAGE_TIMEOUT = timedelta(minutes=3)
 9	DATABASE_TIMEOUT = timedelta(minutes=2)
10	HEARTBEAT_TIMEOUT = timedelta(seconds=30)
11	
12	
13	@workflow.defn(name="CsvImportWorkflow")
14	class CsvImportWorkflow:
15	    @workflow.run
16	    async def run(self, job_id: str) -> None:
17	        try:
18	            for pass_number in range(3):
19	                generation = await workflow.execute_activity(
20	                    "Stage",
21	                    args=[job_id, pass_number],
22	                    result_type=str,
23	                    start_to_close_timeout=STAGE_TIMEOUT,
24	                    heartbeat_timeout=HEARTBEAT_TIMEOUT,
25	                    retry_policy=RETRY,
26	                )
27	                if not generation:
28	                    return
29	                finished = await workflow.execute_activity(
30	                    "Apply",
31	                    args=[job_id, generation],
32	                    result_type=bool,
33	                    start_to_close_timeout=DATABASE_TIMEOUT,
34	                    retry_policy=RETRY,
35	                )
36	                if finished:
37	                    return
38	        except ActivityError as failure:
39	            cause = failure.cause
40	            code = (
41	                cause.type
42	                if isinstance(cause, ApplicationError) and cause.non_retryable
43	                else "IMPORT_PROCESSING_FAILED"
44	            )
45	        else:
46	            code = "STAGING_UNAVAILABLE"
47	
48	        await workflow.execute_activity(
49	            "Fail",
50	            args=[job_id, code],
51	            start_to_close_timeout=DATABASE_TIMEOUT,
52	            retry_policy=RETRY,
53	        )
