23	                if update.HasField("rows_read"):
24	                    activity.heartbeat(update.rows_read)
25	                elif update.HasField("generation"):
26	                    generation = update.generation
27	            if generation is None:
28	                raise RuntimeError("Import staging ended without a result")
29	            return generation
30	        except aio.AioRpcError as error:
31	            if error.code() == StatusCode.INVALID_ARGUMENT:
32	                raise ApplicationError(
