 15	@Service
 16	class ImportDeltaApply {
 17	    private final JdbcClient jdbc;
 18	    private final JdbcTemplate statements;
 19	    private final ImportStaging staging;
 20	    private final InventoryWriteLock inventoryLock;
 21	    private final String candidates = sql("delta-candidates.sql");
 22	    private final String versions = sql("delta-insert-versions.sql");
 23	    private final String[] dimensions = sql("delta-dimensions.sql").split(";");
 24	
 25	    ImportDeltaApply(JdbcClient jdbc, JdbcTemplate statements, ImportStaging staging, InventoryWriteLock inventoryLock) {
 26	        this.jdbc = jdbc;
 27	        this.statements = statements;
 28	        this.staging = staging;
 29	        this.inventoryLock = inventoryLock;
 30	    }
 31	
 32	    @Transactional
 33	    public boolean apply(UUID job, UUID generation) {
 34	        var claim = jdbc.sql("""
 35	                SELECT status, staging_generation, force_overwrite
 36	                FROM import_jobs WHERE job_id = :job FOR UPDATE
 37	                """).param("job", job).query(Claim.class).optional();
 38	        if (claim.isEmpty() || !claim.get().status().equals("RUNNING")) {
 39	            return true; // Already committed, or fenced out by a terminal result.
 40	        }
 41	        var current = claim.get();
 42	        if (!generation.equals(current.stagingGeneration()) || !complete(job, generation)) {
 43	            return false;
 44	        }
 45	        inventoryLock.acquireShared();
 46	        reserveAndLockFrames(job, generation);
 47	        jdbc.sql(candidates).param("job", job).param("generation", generation)
 48	            .param("force", current.forceOverwrite()).update();
 49	
 50	        for (var statement : dimensions) {
 51	            statements.execute(statement);
 52	        }
 53	        statements.update("""
 54	            UPDATE frame_version v SET is_current = false, valid_to = c.transition_at
 55	            FROM import_delta_candidates c
 56	            WHERE v.version_id = c.previous_id AND c.is_current AND c.outcome IN ('APPLY', 'APPLY_FORCE')
 57	            """);
 58	        jdbc.sql(versions).param("job", job).update();
 59	        writeChildren(job);
 60	        writeErrors(job);
 61	        finish(job);
 62	        staging.clear(job);
 63	        return true;
 64	    }
 65	
 66	    @Transactional
 67	    public void fail(UUID job, String code) {
 68	        int updated = jdbc.sql("""
 69	                UPDATE import_jobs SET status = 'FAILED', finished_at = clock_timestamp(), failure_code = :code
 70	                WHERE job_id = :job AND status IN ('PENDING', 'RUNNING')
 71	                """).param("job", job).param("code", code).update();
 72	        if (updated == 1) {
 73	            staging.clear(job);
 74	        }
 75	    }
 76	
 77	    private boolean complete(UUID job, UUID generation) {
 78	        return jdbc.sql("""
 79	                SELECT EXISTS (
 80	                    SELECT 1 FROM stg_inventory_import_completion m
 81	                    WHERE m.job_id = :job AND m.generation = :generation AND m.row_count = (
 82	                        SELECT count(*) FROM stg_inventory_import s
 83	                        WHERE s.job_id = m.job_id AND s.generation = m.generation
 84	                    )
 85	                )
 86	                """).param("job", job).param("generation", generation).query(Boolean.class).single();
 87	    }
