 89	    private void reserveAndLockFrames(UUID job, UUID generation) {
 90	        jdbc.sql("""
 91	                INSERT INTO frame (frame_id)
 92	                SELECT frame_id FROM stg_inventory_import
 93	                WHERE job_id = :job AND generation = :generation AND frame_id IS NOT NULL
 94	                GROUP BY frame_id HAVING count(*) = 1 AND bool_and(payload IS NOT NULL)
 95	                ORDER BY frame_id ON CONFLICT (frame_id) DO NOTHING
 96	                """).param("job", job).param("generation", generation).update();
 97	        jdbc.sql("""
 98	                SELECT f.frame_id FROM frame f
 99	                JOIN (
100	                    SELECT frame_id FROM stg_inventory_import
101	                    WHERE job_id = :job AND generation = :generation AND frame_id IS NOT NULL
102	                    GROUP BY frame_id HAVING count(*) = 1 AND bool_and(payload IS NOT NULL)
103	                ) s USING (frame_id)
104	                ORDER BY f.frame_id FOR UPDATE OF f
105	                """).param("job", job).param("generation", generation).query(String.class).list();
106	    }
107	
108	    private void writeChildren(UUID job) {
109	        jdbc.sql("""
110	                INSERT INTO frame_version_external_reference (version_id, reference_type, reference_value)
111	                SELECT v.version_id, ref.key, ref.value
112	                FROM import_delta_candidates c
113	                JOIN frame_version v ON v.frame_id = c.frame_id AND v.import_job_id = :job AND v.is_current
114	                CROSS JOIN LATERAL jsonb_each_text(c.payload -> 'refs') ref
115	                WHERE c.outcome IN ('APPLY', 'APPLY_FORCE')
116	                """).param("job", job).update();
117	        jdbc.sql("""
118	                INSERT INTO frame_version_link (version_id, position, linked_frame_id)
119	                SELECT v.version_id, link.position, link.target
120	                FROM import_delta_candidates c
121	                JOIN frame_version v ON v.frame_id = c.frame_id AND v.import_job_id = :job AND v.is_current
122	                CROSS JOIN LATERAL jsonb_array_elements_text(c.payload -> 'links') WITH ORDINALITY link(target, position)
123	                WHERE c.outcome IN ('APPLY', 'APPLY_FORCE')
124	                """).param("job", job).update();
125	    }
126	
127	    private void writeErrors(UUID job) {
128	        jdbc.sql("""
129	                INSERT INTO import_row_errors (job_id, row_number, code, frame_id, detail)
130	                SELECT :job, row_number, outcome, frame_id,
131	                    CASE outcome
132	                        WHEN 'DUPLICATE_FRAME_ID' THEN 'More than one record has this frame ID.'
133	                        WHEN 'MANUALLY_DELETED' THEN 'Restoring a manually deleted frame requires force overwrite.'
134	                        WHEN 'STALE_RECORD' THEN 'The source modification time is older than the current frame.'
135	                        WHEN 'TIMESTAMP_COLLISION_CONFLICT' THEN concat(
136	                            'Same source modification time with different payload hashes. Current SHA-256 ',
137	                            encode(previous_hash, 'hex'), '; incoming SHA-256 ', encode(incoming_hash, 'hex'), '.')
138	                        ELSE error_detail
139	                    END
140	                FROM import_delta_candidates
141	                WHERE outcome NOT IN ('APPLY', 'APPLY_FORCE', 'UNCHANGED')
142	                """).param("job", job).update();
143	    }
144	
145	    private void finish(UUID job) {
146	        jdbc.sql("""
147	                UPDATE import_jobs SET finished_at = clock_timestamp(),
148	                    status = CASE WHEN totals.rejected > 0 THEN 'COMPLETED_WITH_ERRORS' ELSE 'COMPLETED' END,
149	                    rows_read = totals.read, rows_applied = totals.applied,
150	                    rows_unchanged = totals.unchanged, rows_rejected = totals.rejected
151	                FROM (
152	                    SELECT count(*) AS read,
153	                           count(*) FILTER (WHERE outcome IN ('APPLY', 'APPLY_FORCE')) AS applied,
154	                           count(*) FILTER (WHERE outcome = 'UNCHANGED') AS unchanged,
155	                           count(*) FILTER (WHERE outcome NOT IN ('APPLY', 'APPLY_FORCE', 'UNCHANGED')) AS rejected
156	                    FROM import_delta_candidates
157	                ) totals WHERE job_id = :job
158	                """).param("job", job).update();
159	    }
