161	    private static String sql(String filename) {
162	        try {
163	            return new ClassPathResource("inventory-import/" + filename).getContentAsString(StandardCharsets.UTF_8);
164	        } catch (IOException error) {
165	            throw new UncheckedIOException(error);
166	        }
167	    }
168	
169	    private record Claim(String status, UUID stagingGeneration, boolean forceOverwrite) {}
170	}
