  9	import io.micrometer.core.instrument.MeterRegistry;
 10	import io.micrometer.core.instrument.Timer;
 11	import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
 12	import org.springframework.context.annotation.Profile;
 13	import org.springframework.stereotype.Service;
 14	import software.amazon.awssdk.services.s3.S3Client;
 15	
 16	@Service
 17	@Profile("local-import")
 18	@ConditionalOnProperty(name = "inventory.import.dispatch.enabled", havingValue = "true")
 19	class ImportProcessing {
 20	    private static final long MAX_BYTES = 10L * 1024 * 1024;
 21	    private static final int BATCH_SIZE = 200;
 22	
 23	    private final ImportStaging staging;
 24	    private final ImportDeltaApply delta;
 25	    private final InventoryCsvReader reader;
 26	    private final S3Client s3;
 27	    private final Timer applyDuration;
 28	
 29	    ImportProcessing(ImportStaging staging, ImportDeltaApply delta, InventoryCsvReader reader, S3Client s3,
 30	                     MeterRegistry registry) {
 31	        this.staging = staging;
 32	        this.delta = delta;
 33	        this.reader = reader;
 34	        this.s3 = s3;
 35	        applyDuration = Timer.builder("inventory.import.apply")
 36	            .description("Time spent in each import apply activity attempt")
 37	            .publishPercentileHistogram()
 38	            .register(registry);
 39	    }
 40	
 41	    String stage(UUID job, int sequence, IntConsumer progress) {
 42	        UUID generation = UUID.randomUUID();
 43	        var claim = staging.claim(job, generation, sequence);
 44	        if (claim.isEmpty()) {
 45	            return "";
 46	        }
 47	        var object = claim.get();
 48	        progress.accept(0);
 49	        try (var stream = s3.getObject(request -> request.bucket(object.objectBucket())
 50	                .key(object.objectKey()).versionId(object.objectVersionId()))) {
 51	            if (stream.response().contentLength() > MAX_BYTES) {
 52	                stream.abort();
 53	                throw new InventoryCsvReader.FileProblem("UPLOAD_TOO_LARGE");
 54	            }
 55	            var batch = new ArrayList<InventoryCsvReader.Row>(BATCH_SIZE);
 56	            int count = reader.read(stream, row -> {
 57	                batch.add(row);
 58	                if (batch.size() == BATCH_SIZE) {
 59	                    staging.append(job, generation, batch);
 60	                    batch.clear();
 61	                    progress.accept(row.number());
 62	                }
 63	            });
 64	            if (!batch.isEmpty()) {
 65	                staging.append(job, generation, batch);
 66	            }
 67	            staging.complete(job, generation, count);
 68	            progress.accept(count);
 69	            return generation.toString();
 70	        } catch (IOException readFailure) {
 71	            throw new UncheckedIOException(readFailure);
 72	        }
 73	    }
 74	
 75	    boolean apply(UUID job, UUID generation) {
 76	        return applyDuration.record(() -> delta.apply(job, generation));
 77	    }
 78	
 79	    void fail(UUID job, String code) {
 80	        delta.fail(job, code);
 81	    }
 82	}
