 10	import org.springframework.jdbc.core.simple.JdbcClient;
 11	import org.springframework.stereotype.Repository;
 12	import org.springframework.transaction.annotation.Transactional;
 13	
 14	@Repository
 15	class ImportStaging {
 16	    private final JdbcClient jdbc;
 17	    private final NamedParameterJdbcTemplate batches;
 18	
 19	    ImportStaging(JdbcClient jdbc, NamedParameterJdbcTemplate batches) {
 20	        this.jdbc = jdbc;
 21	        this.batches = batches;
 22	    }
 23	
 24	    @Transactional
 25	    public Optional<ObjectVersion> claim(UUID job, UUID generation, int sequence) {
 26	        var input = jdbc.sql("""
 27	                UPDATE import_jobs
 28	                SET status = 'RUNNING', staging_generation = :generation, staging_sequence = :sequence
 29	                WHERE job_id = :job AND status IN ('PENDING', 'RUNNING')
 30	                  AND import_mode = 'DELTA' AND object_version_id IS NOT NULL AND staging_sequence < :sequence
 31	                RETURNING object_bucket, object_key, object_version_id
 32	                """).param("job", job).param("generation", generation).param("sequence", sequence)
 33	            .query(ObjectVersion.class).optional();
 34	        if (input.isPresent()) {
 35	            clear(job);
 36	        }
 37	        return input;
 38	    }
 39	
 40	    @Transactional
 41	    public void append(UUID job, UUID generation, List<InventoryCsvReader.Row> rows) {
 42	        requireClaim(job, generation);
 43	        batches.batchUpdate("""
 44	            INSERT INTO stg_inventory_import (job_id, generation, row_number, frame_id, payload, error_code, error_detail)
 45	            VALUES (:job, :generation, :number, :frame, CAST(:payload AS jsonb), :code, :detail)
 46	            """, rows.stream().map(row -> new MapSqlParameterSource()
 47	                .addValue("job", job).addValue("generation", generation).addValue("number", row.number())
 48	                .addValue("frame", row.frameId(), Types.VARCHAR).addValue("payload", row.payload(), Types.VARCHAR)
 49	                .addValue("code", row.errorCode(), Types.VARCHAR).addValue("detail", row.errorDetail(), Types.VARCHAR))
 50	            .toArray(MapSqlParameterSource[]::new));
 51	    }
 52	
 53	    @Transactional
 54	    public void complete(UUID job, UUID generation, int rows) {
 55	        requireClaim(job, generation);
 56	        jdbc.sql("""
 57	                INSERT INTO stg_inventory_import_completion (job_id, generation, row_count)
 58	                VALUES (:job, :generation, :rows)
 59	                """).param("job", job).param("generation", generation).param("rows", rows).update();
 60	    }
 61	
 62	    void clear(UUID job) {
 63	        jdbc.sql("DELETE FROM stg_inventory_import_completion WHERE job_id = :job").param("job", job).update();
 64	        jdbc.sql("DELETE FROM stg_inventory_import WHERE job_id = :job").param("job", job).update();
 65	    }
 66	
 67	    private void requireClaim(UUID job, UUID generation) {
 68	        if (jdbc.sql("""
 69	                SELECT job_id FROM import_jobs
 70	                WHERE job_id = :job AND status = 'RUNNING' AND staging_generation = :generation FOR UPDATE
 71	                """).param("job", job).param("generation", generation).query(UUID.class).optional().isEmpty()) {
 72	            throw new IllegalStateException("Import staging attempt no longer owns the job");
 73	        }
 74	    }
 75	
 76	    record ObjectVersion(String objectBucket, String objectKey, String objectVersionId) {}
 77	}

