     9	import org.slf4j.Logger;
    10	import org.slf4j.LoggerFactory;
    11	import org.springframework.stereotype.Service;
    12	import org.springframework.transaction.annotation.Isolation;
    13	import org.springframework.transaction.annotation.Transactional;
    14	import org.springframework.transaction.support.TransactionSynchronization;
    15	import org.springframework.transaction.support.TransactionSynchronizationManager;
    16	
    17	@Service
    18	class FrameService {
    19	    private static final Logger LOGGER = LoggerFactory.getLogger(FrameService.class);
    20	
    21	    private final FrameRepository frames;
    22	    private final InventoryWriteLock inventoryLock;
    23	    private final Counter framesCreated;
    24	    private final Counter framesUpdated;
    25	    private final Counter framesSoftDeleted;
    26	
    27	    FrameService(FrameRepository frames, MeterRegistry registry, InventoryWriteLock inventoryLock) {
    28	        this.frames = frames;
    29	        this.inventoryLock = inventoryLock;
    30	        this.framesCreated = lifecycleCounter(registry, "created");
    31	        this.framesUpdated = lifecycleCounter(registry, "updated");
    32	        this.framesSoftDeleted = lifecycleCounter(registry, "soft_deleted");
    33	    }
    34	
    35	    @Transactional(readOnly = true, isolation = Isolation.REPEATABLE_READ)
    36	    FramePage list(int page, int size, List<String> statuses, String search) {
    37	        var matches = frames.list((long) page * size, size + 1, statuses, search);
    38	        boolean hasNext = matches.size() > size;
    39	        LOGGER.atInfo()
    40	            .addKeyValue("page", page)
    41	            .addKeyValue("size", size)
    42	            .addKeyValue("totalElements", frames::countCurrent)
    43	            .log("frame.listed");
    44	        return new FramePage(hasNext ? List.copyOf(matches.subList(0, size)) : matches, page, size, hasNext);
    45	    }
    46	
    47	    FrameVersion detail(String frameId) {
    48	        return frames.findCurrent(frameId).orElseThrow(FrameProblem::missing);
    49	    }
    50	
    51	    List<FrameVersion> history(String frameId) {
    52	        var versions = frames.history(frameId);
    53	        if (versions.isEmpty() && !frames.exists(frameId)) {
    54	            throw FrameProblem.missing();
    55	        }
    56	        return versions;
    57	    }
    58	
    59	    @Transactional
    60	    FrameVersion create(String frameId, FrameAttributes attributes) {
    61	        inventoryLock.acquireShared();
    62	        if (!frames.reserveId(frameId)) {
    63	            throw FrameProblem.reserved();
    64	        }
    65	        long versionId = frames.append(frameId, attributes, null, null, "MANUAL_CREATE");
    66	        FrameVersion created = frames.findVersion(versionId);
    67	        afterCommit(() -> {
    68	            framesCreated.increment();
    69	            LOGGER.atInfo()
    70	                .addKeyValue("frameId", frameId)
    71	                .addKeyValue("versionId", versionId)
    72	                .log("frame.created");
    73	        });
    74	        return created;
    75	    }
    76	
    77	    @Transactional
    78	    FrameVersion edit(String frameId, long expectedVersionId, FrameAttributes attributes) {
    79	        inventoryLock.acquireShared();
    80	        Long current = lockAndCheckVersion(frameId, expectedVersionId);
    81	        OffsetDateTime transition = frames.close(current, null);
    82	        long versionId = frames.append(frameId, attributes, current, transition, "MANUAL_EDIT");
    83	        frames.copyVersionChildren(current, versionId);
    84	        FrameVersion updated = frames.findVersion(versionId);
    85	        afterCommit(() -> {
    86	            framesUpdated.increment();
    87	            LOGGER.atInfo()
    88	                .addKeyValue("frameId", frameId)
    89	                .addKeyValue("previousVersionId", current)
    90	                .addKeyValue("newVersionId", versionId)
    91	                .log("frame.updated");
    92	        });
    93	        return updated;
    94	    }
    95	
    96	    @Transactional
    97	    void delete(String frameId, Long expectedVersionId) {
    98	        inventoryLock.acquireShared();
    99	        Long current = lockAndCheckVersion(frameId, expectedVersionId);
   100	        if (current != null) {
   101	            frames.close(current, "MANUAL_DELETE");
   102	            afterCommit(() -> {
   103	                framesSoftDeleted.increment();
   104	                LOGGER.atInfo()
   105	                    .addKeyValue("frameId", frameId)
   106	                    .addKeyValue("closedVersionId", current)
   107	                    .log("frame.soft_deleted");
   108	            });
   109	        }
   110	    }
   111	
   112	    private Long lockAndCheckVersion(String frameId, Long expectedVersionId) {
   113	        if (!frames.lockFrame(frameId)) {
   114	            throw FrameProblem.missing();
   115	        }
   116	        Long current = frames.currentVersionId(frameId).orElse(null);
   117	        LOGGER.atDebug()
   118	            .addKeyValue("frameId", frameId)
   119	            .addKeyValue("expectedVersionId", expectedVersionId)
   120	            .addKeyValue("currentVersionId", current)
   121	            .log("frame.version_checked");
   122	        if (expectedVersionId != null && !expectedVersionId.equals(current)) {
   123	            throw FrameProblem.stale(current);
   124	        }
   125	        return current;
   126	    }
   127	
   128	    private static Counter lifecycleCounter(MeterRegistry registry, String operation) {
   129	        return Counter.builder("frame.lifecycle.changes")
   130	            .description("Committed frame inventory changes")
   131	            .tag("operation", operation)
   132	            .register(registry);
   133	    }
   134	
   135	    private static void afterCommit(Runnable action) {
   136	        if (TransactionSynchronizationManager.isSynchronizationActive()) {
   137	            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
   138	                @Override
   139	                public void afterCommit() {
   140	                    action.run();
   141	                }
   142	            });
   143	        }
   144	    }
   145	
   146	    record FramePage(List<FrameVersion> items, int page, int size, boolean hasNext) {}
   147	}
