    39	    public void start(S3ImportNotifications.Upload upload) {
    40	        var job = jobs.lockBoundUpload(upload.jobId(), upload.version());
    41	        if (job.isEmpty() || !job.get().status().equals("PENDING") || job.get().dispatchConfirmedAt() != null) {
    42	            return;
    43	        }
    44	        var options = WorkflowOptions.newBuilder().setWorkflowId(workflowId(upload.jobId()))
    45	            .setTaskQueue(taskQueue)
    46	            .setWorkflowIdConflictPolicy(WorkflowIdConflictPolicy.WORKFLOW_ID_CONFLICT_POLICY_USE_EXISTING)
    47	            .setWorkflowIdReusePolicy(WorkflowIdReusePolicy.WORKFLOW_ID_REUSE_POLICY_REJECT_DUPLICATE)
    48	            .setWorkflowExecutionTimeout(Duration.ofHours(1))
    49	            .build();
    50	        try {
    51	            temporal.newUntypedWorkflowStub("CsvImportWorkflow", options).start(upload.jobId().toString());
    52	        } catch (WorkflowExecutionAlreadyStarted duplicate) {
    53	            // The stable ID already belongs to this job, even if the execution has closed.
    54	        }
    55	        jobs.confirmDispatch(upload.jobId(), upload.version());
    56	    }
    57	
    58	    @Transactional
    59	    public void reconcileDeadLetter(S3ImportNotifications.Upload upload) {
    60	        var job = jobs.lockBoundUpload(upload.jobId(), upload.version());
    61	        if (job.isEmpty() || !job.get().status().equals("PENDING") || job.get().dispatchConfirmedAt() != null) {
    62	            return;
    63	        }
    64	        var request = DescribeWorkflowExecutionRequest.newBuilder()
    65	            .setNamespace(temporal.getOptions().getNamespace())
    66	            .setExecution(WorkflowExecution.newBuilder().setWorkflowId(workflowId(upload.jobId())))
    67	            .build();
    68	        try {
    69	            temporal.getWorkflowServiceStubs().blockingStub().withDeadlineAfter(5, TimeUnit.SECONDS)
    70	                .describeWorkflowExecution(request);
    71	            jobs.confirmDispatch(upload.jobId(), upload.version());
    72	        } catch (StatusRuntimeException error) {
    73	            if (error.getStatus().getCode() != Status.Code.NOT_FOUND) {
    74	                throw error;
    75	            }
    76	            if (job.get().dispatchUntil().toInstant().isAfter(Instant.now())) {
    77	                throw new DispatchStillReconciling();
    78	            }
    79	            jobs.failDispatch(upload.jobId(), upload.version());
    80	        }
    81	    }
