 28	@Component
 29	class InventoryCsvReader {
 30	    static final int MAX_ROWS = 10_000;
 31	    private static final Set<String> HEADER = Set.of((
 32	        "frame_id,type_classic_digital,format,environment,created_date,modified_date,postcode,"
 33	        + "site_no,inventory_site_no,location,postcode_area,postcode_district,postcode_sector,postcode_unit,"
 34	        + "address,region,country_code,town,illumination_type_id,number_of_slots,status,"
 35	        + "status_reason,longitude,latitude,distance_to_closest_school,panel_number,station,size_code,"
 36	        + "size_group_code,impact_weight,production_rate_card,airport,price_entity_id,broadsign_display_unit_id,broadsign_frame_id,"
 37	        + "broadsign_domain_id,linked_frame_ids,aspect_ratio_code,pixel_height,pixel_width,location_id,t_size,"
 38	        + "premium,production_rate_card_legacy,pricing_grade").split(","));
 39	    private static final List<String> TEXT_FIELDS = List.of(
 40	        "status_reason", "site_no", "inventory_site_no", "panel_number", "location_id", "environment",
 41	        "address", "station", "airport", "size_code", "aspect_ratio_code", "t_size",
 42	        "production_rate_card", "production_rate_card_legacy", "pricing_grade");
 43	    private static final Map<String, String> REFERENCES = Map.of(
 44	        "price_entity_id", "PRICE_ENTITY", "broadsign_display_unit_id", "BROADSIGN_DISPLAY_UNIT",
 45	        "broadsign_frame_id", "BROADSIGN_FRAME", "broadsign_domain_id", "BROADSIGN_DOMAIN");
 46	    private static final Set<String> STATUSES = Set.of("LIVE", "PENDING", "MAINTENANCE", "BLOCKED", "DRAFT");
 47	    private static final CSVFormat FORMAT = CSVFormat.RFC4180.builder().setHeader()
 48	        .setSkipHeaderRecord(true).setDuplicateHeaderMode(DuplicateHeaderMode.DISALLOW).get();
 49	    private static final java.time.format.DateTimeFormatter SOURCE_TIME = new DateTimeFormatterBuilder()
 50	        .appendPattern("uuuu-MM-dd HH:mm:ss")
 51	        .optionalStart().appendFraction(ChronoField.NANO_OF_SECOND, 1, 6, true).optionalEnd()
 52	        .toFormatter(java.util.Locale.ROOT).withResolverStyle(ResolverStyle.STRICT);
 53	
 54	    private final ObjectMapper mapper;
 55	
 56	    InventoryCsvReader(ObjectMapper mapper) {
 57	        this.mapper = mapper;
 58	    }
 59	
 60	    int read(InputStream input, Consumer<Row> sink) {
 61	        var utf8 = StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT)
 62	            .onUnmappableCharacter(CodingErrorAction.REPORT);
 63	        try (var reader = new PushbackReader(new InputStreamReader(input, utf8), 1)) {
 64	            int first = reader.read();
 65	            if (first != -1 && first != '\ufeff') {
 66	                reader.unread(first);
 67	            }
 68	            var parser = parseHeader(reader);
 69	            try (parser) {
 70	                if (!parser.getHeaderMap().keySet().equals(HEADER)) {
 71	                    throw new FileProblem("INVALID_CSV_HEADER");
 72	                }
 73	                int number = 0;
 74	                for (var row : parser) {
 75	                    if (++number > MAX_ROWS) {
 76	                        throw new FileProblem("ROW_LIMIT_EXCEEDED");
 77	                    }
 78	                    sink.accept(parse(number, row, parser.getHeaderMap().get("frame_id")));
 79	                }
 80	                return number;
 81	            }
 82	        } catch (org.apache.commons.csv.CSVException | java.nio.charset.CharacterCodingException invalid) {
 83	            throw new FileProblem("INVALID_CSV");
 84	        } catch (UncheckedIOException wrapped) {
 85	            if (wrapped.getCause() instanceof org.apache.commons.csv.CSVException
 86	                    || wrapped.getCause() instanceof java.nio.charset.CharacterCodingException) {
 87	                throw new FileProblem("INVALID_CSV");
 88	            }
 89	            throw wrapped;
 90	        } catch (IOException inputFailure) {
 91	            throw new UncheckedIOException(inputFailure);
 92	        }
 93	    }
 94	
 95	    private static org.apache.commons.csv.CSVParser parseHeader(PushbackReader reader) throws IOException {
 96	        try {
 97	            return FORMAT.parse(reader);
 98	        } catch (IllegalArgumentException invalid) {
 99	            throw new FileProblem("INVALID_CSV_HEADER");
100	        }
101	    }
102	
103	    private Row parse(int number, CSVRecord row, int idIndex) {
104	        String id = idIndex < row.size() ? text(row.get(idIndex)) : null;
105	        if (id != null && (id.length() > 128 || id.indexOf('\0') >= 0)) {
106	            id = null;
107	        }
108	        if (!row.isConsistent()) {
109	            return invalid(number, id, "COLUMN_COUNT", "The record has a different number of fields than the CSV header.");
110	        }
111	        if (id == null) {
112	            return invalid(number, null, "INVALID_FRAME_ID", "Frame ID must contain 1–128 characters.");
113	        }
114	        try {
115	            ObjectNode payload = mapper.createObjectNode();
116	            for (var field : TEXT_FIELDS) {
117	                payload.put(field, field(row, field));
118	            }
119	            var status = field(row, "status");
120	            if (status == null || !STATUSES.contains(status)) {
121	                throw new InvalidField("status");
122	            }
123	            payload.put("status", status);
124	            payload.put("source_created_at", timestamp(row, "created_date", false));
125	            payload.put("source_modified_at", timestamp(row, "modified_date", true));
126	
127	            payload.put("longitude", decimal(row, "longitude", 180));
128	            payload.put("latitude", decimal(row, "latitude", 90));
129	            payload.put("impact_weight", decimal(row, "impact_weight", 0));
130	            payload.put("distance_to_closest_school", integer(row, "distance_to_closest_school", 0));
131	            payload.put("number_of_slots", integer(row, "number_of_slots", 0));
132	            payload.put("illumination_type_id", integer(row, "illumination_type_id", Integer.MIN_VALUE));
133	            payload.put("pixel_height", integer(row, "pixel_height", 1));
134	            payload.put("pixel_width", integer(row, "pixel_width", 1));
135	
136	            String premium = field(row, "premium");
137	            if (premium != null && !premium.equals("0") && !premium.equals("1")) {
138	                throw new InvalidField("premium");
139	            }
140	            payload.put("premium", "1".equals(premium));
141	            addDimensions(row, payload);
142	
143	            var references = payload.putObject("refs");
144	            REFERENCES.forEach((column, type) -> {
145	                var value = field(row, column);
146	                if (value != null) {
147	                    references.put(type, value);
148	                }
149	            });
150	            var links = payload.putArray("links");
151	            var csvLinks = field(row, "linked_frame_ids");
152	            if (csvLinks != null) {
153	                for (String target : csvLinks.split(",", -1)) {
154	                    String normalized = text(target);
155	                    if (normalized == null || normalized.length() > 128) {
156	                        throw new InvalidField("linked_frame_ids");
157	                    }
158	                    links.add(normalized);
159	                }
160	            }
161	            return new Row(number, id, payload.toString(), null, null);
162	        } catch (InvalidField invalid) {
163	            return invalid(number, id, "INVALID_FIELD", "Invalid value for " + invalid.field + ".");
164	        }
165	    }
166	
167	    private static void addDimensions(CSVRecord row, ObjectNode payload) {
168	        String country = field(row, "country_code");
169	        String region = field(row, "region");
170	        String town = field(row, "town");
171	        String postcode = field(row, "postcode");
172	        if (country != null || region != null || town != null || postcode != null) {
173	            if (country == null || !country.matches("[A-Z]{2}")) throw new InvalidField("country_code");
174	            requireLength(region, 128, "region");
175	            requireLength(town, 128, "town");
176	            if (postcode == null || !postcode.matches("[A-Z0-9][A-Z0-9 -]{0,31}")) throw new InvalidField("postcode");
177	        }
178	        payload.put("country_code", country).put("region_name", region)
179	            .put("town_name", town).put("postcode", postcode);
180	
181	        String technology = field(row, "type_classic_digital");
182	        String format = field(row, "format");
183	        String sizeGroup = field(row, "size_group_code");
184	        if (technology != null || format != null || sizeGroup != null) {
185	            if (!"CLASSIC".equals(technology) && !"DIGITAL".equals(technology)) {
186	                throw new InvalidField("type_classic_digital");
187	            }
188	            requireLength(format, 128, "format");
189	            requireLength(sizeGroup, 128, "size_group_code");
190	        }
191	        payload.put("technology_code", technology).put("format_code", format).put("size_group_code", sizeGroup);
192	    }
193	
194	    private static void requireLength(String value, int max, String field) {
195	        if (value == null || value.length() > max) throw new InvalidField(field);
196	    }
197	
198	    private static String field(CSVRecord row, String name) {
199	        String value = text(row.get(name));
200	        if (value != null && value.indexOf('\0') >= 0) {
201	            throw new InvalidField(name);
202	        }
203	        return value;
204	    }
