 67	    private void requireClaim(UUID job, UUID generation) {
 68	        if (jdbc.sql("""
 69	                SELECT job_id FROM import_jobs
 70	                WHERE job_id = :job AND status = 'RUNNING' AND staging_generation = :generation FOR UPDATE
 71	                """).param("job", job).param("generation", generation).query(UUID.class).optional().isEmpty()) {
 72	            throw new IllegalStateException("Import staging attempt no longer owns the job");
 73	        }
 74	    }
