    22	@Component
    23	@GlobalServerInterceptor
    24	@Order(Ordered.HIGHEST_PRECEDENCE)
    25	public class CorrelationIdInterceptor implements ServerInterceptor {
    26	    private static final Logger LOGGER = LoggerFactory.getLogger(CorrelationIdInterceptor.class);
    27	    private static final Metadata.Key<String> HEADER =
    28	            Metadata.Key.of("x-correlation-id", Metadata.ASCII_STRING_MARSHALLER);
    29	    private static final Pattern UUID_PATTERN =
    30	Pattern.compile("[A-Fa-f0-9]{8}(-[A-Fa-f0-9]{4}){3}-[A-Fa-f0-9]{12}");
    31	    private static final String LOG_FIELD = "correlationId";
    32	
    33	    @Override
    34	    public <ReqT, RespT> ServerCall.Listener<ReqT> interceptCall(
    35	            ServerCall<ReqT, RespT> call, Metadata headers, ServerCallHandler<ReqT, RespT> next) {
    36	        String suppliedId = headers.get(HEADER);
    37	        String correlationId = suppliedId != null && UUID_PATTERN.matcher(suppliedId).matches()
    38	                ? suppliedId : UUID.randomUUID().toString();
    39	        var loggingCall = new ForwardingServerCall.SimpleForwardingServerCall<ReqT, RespT>(call) {
    40	            @Override
    41	            public void close(Status status, Metadata trailers) {
    42	                switch (status.getCode()) {
    43	                    case UNKNOWN, INTERNAL, DATA_LOSS -> withCorrelationId(correlationId, () -> {
    44	                        LOGGER.atError()
    45	                            .addKeyValue("rpc", call.getMethodDescriptor().getFullMethodName())
    46	                            .addKeyValue("grpcStatus", status.getCode().name())
    47	                            .setCause(status.getCause())
    48	                            .log("grpc.server_error");
    49	                        return null;
    50	                    });
    51	                    default -> { }
    52	                }
    53	                super.close(status, trailers);
    54	            }
    55	        };
    56	        var listener = withCorrelationId(correlationId, () -> next.startCall(loggingCall, headers));
    57	
    58	        return new ForwardingServerCallListener.SimpleForwardingServerCallListener<>(listener) {
    59	            @Override
    60	            public void onHalfClose() {
    61	                withCorrelationId(correlationId, () -> {
    62	                    super.onHalfClose();
    63	                    return null;
    64	                });
    65	            }
    66	        };
    67	    }
    68	
    69	    private static <T> T withCorrelationId(String correlationId, Supplier<T> action) {
    70	        String previous = MDC.get(LOG_FIELD);
    71	        MDC.put(LOG_FIELD, correlationId);
    72	        try {
    73	            return action.get();
    74	        } finally {
    75	            if (previous == null) {
    76	                MDC.remove(LOG_FIELD);
    77	            } else {
    78	                MDC.put(LOG_FIELD, previous);
    79	            }
    80	        }
    81	    }
    82	}

