    12	@Service
    13	@Profile("local-import")
    14	@ConditionalOnProperty(name = "inventory.import.dispatch.enabled", havingValue = "true")
    15	class ImportDispatch {
    16	    private static final long MAX_UPLOAD_BYTES = 10L * 1024 * 1024;
    17	    private final S3ImportNotifications notifications;
    18	    private final ImportJobRepository jobs;
    19	    private final S3Client s3;
    20	    private final ImportTemporalDispatch temporal;
    21	    private final String bucket;
    22	
    23	    ImportDispatch(S3ImportNotifications notifications, ImportJobRepository jobs, S3Client s3,
    24	                   ImportTemporalDispatch temporal, @Value("${inventory.import.bucket}") String bucket) {
    25	        this.notifications = notifications;
    26	        this.jobs = jobs;
    27	        this.s3 = s3;
    28	        this.temporal = temporal;
    29	        this.bucket = bucket;
    30	    }
    31	
    32	    void dispatch(String message) {
    33	        forEachUpload(notifications.parse(message, bucket), this::dispatchUpload);
    34	    }
    35	
    36	    void reconcileDeadLetter(String message) {
    37	        forEachUpload(notifications.parse(message, bucket), upload -> {
    38	            var job = jobs.findUpload(upload.jobId(), upload.bucket(), upload.key());
    39	            if (job.isEmpty()) {
    40	                return;
    41	            }
    42	            if (job.get().status().equals("AWAITING_UPLOAD")) {
    43	                // The bind never committed. No workflow could have been started for this upload.
    44	                jobs.failUnboundDispatch(upload.jobId(), upload.bucket(), upload.key(), upload.uploadedAt());
    45	            }
    46	            temporal.reconcileDeadLetter(upload);
    47	        });
    48	    }
    49	
    50	    private void dispatchUpload(S3ImportNotifications.Upload upload) {
    51	        var job = jobs.findUpload(upload.jobId(), upload.bucket(), upload.key());
    52	        if (job.isEmpty()) {
    53	            return;
    54	        }
    55	        var existing = job.get();
    56	        if (existing.status().equals("AWAITING_UPLOAD")) {
    57	            if (!existing.dispatchUntil().toInstant().isAfter(Instant.now())) {
    58	                return;
    59	            }
    60	            var head = s3.headObject(request -> request.bucket(upload.bucket())
    61	                .key(upload.key()).versionId(upload.version()));
    62	            if (head.contentLength() > MAX_UPLOAD_BYTES) {
    63	                jobs.rejectOversizedUpload(upload.jobId(), upload.bucket(), upload.key(), upload.uploadedAt());
    64	                return;
    65	            }
    66	            if (!jobs.bindUpload(upload.jobId(), upload.bucket(), upload.key(), upload.version(), upload.uploadedAt())) {
    67	                return;
    68	            }
    69	        } else if (!existing.status().equals("PENDING") || !upload.version().equals(existing.objectVersionId())) {
    70	            return;
    71	        }
    72	        temporal.start(upload);
    73	    }
    74	
    75	    private static void forEachUpload(List<S3ImportNotifications.Upload> uploads,
    76	                                      java.util.function.Consumer<S3ImportNotifications.Upload> handler) {
    77	        RuntimeException firstFailure = null;
    78	        for (var upload : uploads) {
    79	            try {
    80	                handler.accept(upload);
    81	            } catch (RuntimeException failure) {
    82	                if (firstFailure == null) {
    83	                    firstFailure = failure;
    84	                }
    85	            }
    86	        }
    87	        if (firstFailure != null) {
    88	            throw firstFailure;
    89	        }
    90	    }
