  1	CREATE TEMP TABLE import_delta_candidates ON COMMIT DROP AS
  2	WITH staged AS (
  3	    SELECT s.*, count(*) OVER (PARTITION BY frame_id) AS copies
  4	    FROM stg_inventory_import s
  5	    WHERE job_id = :job AND generation = :generation
  6	), previous AS (
  7	    SELECT s.*, v.version_id AS previous_id, v.is_current, v.valid_from, v.valid_to,
  8	           v.closed_by_change_source,
  9	           CASE WHEN v.legacy_manual_source OR v.source_modified_at IS NULL
 10	                THEN v.valid_from AT TIME ZONE 'UTC' ELSE v.source_modified_at END AS baseline,
 11	           (s.payload ->> 'source_modified_at')::timestamp AS incoming_timestamp,
 12	           sha256(convert_to('inventory-frame-payload-v1:' || (s.payload - ARRAY['source_created_at', 'source_modified_at'])::text, 'UTF8')) AS incoming_hash,
 13	           sha256(convert_to('inventory-frame-payload-v1:' || (
 14	               (to_jsonb(v) - ARRAY['version_id', 'frame_id', 'postcode_id', 'frame_format_id',
 15	                   'source_created_at', 'source_modified_at', 'valid_from', 'valid_to', 'is_current',
 16	                   'change_source', 'closed_by_change_source', 'import_job_id', 'legacy_manual_source'])
 17	               || jsonb_build_object('latitude', trim_scale(v.latitude), 'longitude', trim_scale(v.longitude),
 18	                   'impact_weight', trim_scale(v.impact_weight), 'country_code', r.country_code,
 19	                   'region_name', r.region_name, 'town_name', t.town_name, 'postcode', p.postcode,
 20	                   'technology_code', f.technology_code, 'format_code', f.format_code,
 21	                   'size_group_code', f.size_group_code, 'refs', coalesce((
 22	                       SELECT jsonb_object_agg(ref.reference_type, ref.reference_value)
 23	                       FROM frame_version_external_reference ref WHERE ref.version_id = v.version_id
 24	                   ), '{}'::jsonb), 'links', coalesce((
 25	                       SELECT jsonb_agg(link.linked_frame_id ORDER BY link.position)
 26	                       FROM frame_version_link link WHERE link.version_id = v.version_id
 27	                   ), '[]'::jsonb))
 28	           )::text, 'UTF8')) AS previous_hash
 29	    FROM staged s
 30	    LEFT JOIN LATERAL (
 31	        SELECT fv.* FROM frame_version fv
 32	        WHERE fv.frame_id = s.frame_id AND s.payload IS NOT NULL AND s.copies = 1
 33	        ORDER BY fv.is_current DESC, fv.valid_from DESC, fv.version_id DESC LIMIT 1
 34	    ) v ON true
 35	    LEFT JOIN postcode p ON p.postcode_id = v.postcode_id
 36	    LEFT JOIN town t ON t.town_id = p.town_id
 37	    LEFT JOIN region r ON r.region_id = t.region_id
 38	    LEFT JOIN frame_format f ON f.frame_format_id = v.frame_format_id
 39	)
 40	SELECT row_number, frame_id, payload, error_detail, previous_id, is_current, previous_hash, incoming_hash,
 41	       CASE
 42	           WHEN frame_id IS NOT NULL AND copies > 1 THEN 'DUPLICATE_FRAME_ID'
 43	           WHEN error_code IS NOT NULL THEN error_code
 44	           WHEN previous_id IS NULL THEN 'APPLY'
 45	           WHEN NOT is_current AND closed_by_change_source = 'MANUAL_DELETE'
 46	               THEN CASE WHEN :force THEN 'APPLY_FORCE' ELSE 'MANUALLY_DELETED' END
 47	           WHEN incoming_timestamp > baseline THEN 'APPLY'
 48	           WHEN incoming_timestamp = baseline AND incoming_hash = previous_hash THEN 'UNCHANGED'
 49	           WHEN :force THEN 'APPLY_FORCE'
 50	           WHEN incoming_timestamp < baseline THEN 'STALE_RECORD'
 51	           ELSE 'TIMESTAMP_COLLISION_CONFLICT'
 52	       END AS outcome,
 53	       CASE WHEN previous_id IS NULL THEN clock_timestamp()
 54	            ELSE greatest(clock_timestamp(), valid_from + interval '1 microsecond', valid_to)
 55	       END AS transition_at
 56	FROM previous
