 32	    public void createImportJob(CreateImportJobRequest request, StreamObserver<CreateImportJobResponse> response) {
 33	        String owner = LocalImportIdentity.requireOperator();
 34	        switch (request.getMode()) {
 35	            case FULL_SNAPSHOT -> throw Status.FAILED_PRECONDITION
 36	                .withDescription("Full snapshot imports are disabled").asRuntimeException();
 37	            case UNRECOGNIZED -> throw Status.INVALID_ARGUMENT
 38	                .withDescription("Unsupported import mode").asRuntimeException();
 39	            default -> { }
