 52	    public void listImportRowErrors(ListImportRowErrorsRequest request,
 53	                                    StreamObserver<ListImportRowErrorsResponse> response) {
 54	        int page = request.getPage();
 55	        int size = request.hasSize() ? request.getSize() : 25;
 56	        if (page < 0 || size < 1 || size > 50) {
 57	            throw Status.INVALID_ARGUMENT.withDescription("Page must be nonnegative and size must be 1–50")
 58	                .asRuntimeException();
 59	        }
 60	        var errors = jobs.errors(jobId(request.getJobId()), LocalImportIdentity.requireOperator(), page, size);
 61	        var result = ListImportRowErrorsResponse.newBuilder().setPage(page).setSize(size)
 62	            .setHasNext(errors.hasNext());
 63	        for (var row : errors.items()) {
 64	            var error = ImportRowError.newBuilder().setRowNumber(row.rowNumber())
 65	                .setCode(row.code()).setDetail(row.detail());
 66	            if (row.frameId() != null) {
 67	                error.setFrameId(row.frameId());
 68	            }
 69	            result.addItems(error);
 70	        }
 71	        reply(response, result.build());
 72	    }
