 14	@Component
 15	@Profile("local-import")
 16	@ConditionalOnProperty(name = "inventory.import.dispatch.enabled", havingValue = "true")
 17	class ImportQueuePoller {
 18	    private static final Logger LOGGER = LoggerFactory.getLogger(ImportQueuePoller.class);
 19	    private final SqsClient sqs;
 20	    private final ImportDispatch dispatch;
 21	    private final String queueUrl;
 22	    private final String dlqUrl;
 23	
 24	    ImportQueuePoller(SqsClient sqs, ImportDispatch dispatch,
 25	                      @Value("${inventory.import.dispatch.queue-url}") String queueUrl,
 26	                      @Value("${inventory.import.dispatch.dlq-url}") String dlqUrl) {
 27	        this.sqs = sqs;
 28	        this.dispatch = dispatch;
 29	        this.queueUrl = queueUrl;
 30	        this.dlqUrl = dlqUrl;
 31	    }
 32	
 33	    @Scheduled(fixedDelay = 250)
 34	    void pollSource() {
 35	        poll(queueUrl, false);
 36	    }
 37	
 38	    @Scheduled(fixedDelay = 2_000)
 39	    void pollDeadLetters() {
 40	        poll(dlqUrl, true);
 41	    }
 42	
 43	    private void poll(String url, boolean deadLetter) {
 44	        try {
 45	            var received = sqs.receiveMessage(request -> request.queueUrl(url).waitTimeSeconds(1)
 46	                .maxNumberOfMessages(1)
 47	                .messageSystemAttributeNames(MessageSystemAttributeName.APPROXIMATE_RECEIVE_COUNT));
 48	            for (var message : received.messages()) {
 49	                handle(url, message, deadLetter);
 50	            }
 51	        } catch (RuntimeException failure) {
 52	            LOGGER.warn("Import queue operation failed (deadLetter={}, error={})",
 53	                deadLetter, failure.getClass().getSimpleName());
 54	        }
 55	    }
 56	
 57	    private void handle(String url, Message message, boolean deadLetter) {
 58	        try {
 59	            if (deadLetter) {
 60	                dispatch.reconcileDeadLetter(message.body());
 61	            } else {
 62	                dispatch.dispatch(message.body());
 63	            }
 64	        } catch (S3ImportNotifications.InvalidNotification invalid) {
 65	            LOGGER.warn("Invalid S3 import notification (deadLetter={})", deadLetter);
 66	            if (!deadLetter) {
 67	                defer(url, message, false);
 68	                return;
 69	            }
 70	            // An invalid envelope cannot safely identify a job.
 71	        } catch (ImportTemporalDispatch.DispatchStillReconciling pending) {
 72	            defer(url, message, deadLetter);
 73	            return;
 74	        } catch (RuntimeException failure) {
 75	            LOGGER.warn("Import message will retry (deadLetter={}, error={})",
 76	                deadLetter, failure.getClass().getSimpleName());
 77	            defer(url, message, deadLetter);
 78	            return;
 79	        }
 80	        sqs.deleteMessage(request -> request.queueUrl(url).receiptHandle(message.receiptHandle()));
 81	    }
 82	
 83	    private void defer(String url, Message message, boolean deadLetter) {
 84	        int receives = Integer.parseInt(message.attributes()
 85	            .getOrDefault(MessageSystemAttributeName.APPROXIMATE_RECEIVE_COUNT, "1"));
 86	        int seconds = deadLetter ? 60 : Math.min(60, 5 << Math.min(4, Math.max(0, receives - 1)));
 87	        sqs.changeMessageVisibility(request -> request.queueUrl(url)
 88	            .receiptHandle(message.receiptHandle()).visibilityTimeout(seconds));
 89	    }
 90	}
